// Exports the demo catalogue (single source of truth: src/fixtures/catalogue.ts) as SQL for the
// backend repo's supabase/seed.sql. Usage: node scripts/export-catalogue-sql.mjs ../backend/supabase/seed.sql
import { writeFileSync } from 'node:fs';
import { AIRPORTS, PROGRAMS, TRANSFER_ROUTES } from '../src/fixtures/catalogue.ts';

const q = (v) => (v === undefined || v === null ? 'null' : `'${String(v).replaceAll("'", "''")}'`);
const arr = (xs) => `array[${xs.map(q).join(', ')}]::text[]`;

const out = [
  '-- Generated by frontend/scripts/export-catalogue-sql.mjs from src/fixtures/catalogue.ts. Do not edit by hand.',
  '-- Demo catalogue: transfer rules are UNVERIFIED or ILLUSTRATIVE unless a source and check date are present.',
  '',
  'insert into public.airports (iata, name, city, country, tz, lat, lon) values',
  AIRPORTS.map(
    (a) =>
      `  (${q(a.iata)}, ${q(a.name)}, ${q(a.city)}, ${q(a.country)}, ${q(a.tz)}, ${a.lat}, ${a.lon})`,
  ).join(',\n') + ';',
  '',
  'insert into public.loyalty_programs (id, name, unit, kind, website) values',
  PROGRAMS.map(
    (p) => `  (${q(p.id)}, ${q(p.name)}, ${q(p.unit)}, ${q(p.kind)}, ${q(p.website)})`,
  ).join(',\n') + ';',
  '',
  'insert into public.transfer_routes (id, from_program, to_program, ratio_num, ratio_den, min_points, increment, status, verification, max_delay_days, preconditions, source_url, checked_at) values',
  TRANSFER_ROUTES.map(
    (r) =>
      `  (${q(r.id)}, ${q(r.from)}, ${q(r.to)}, ${r.num}, ${r.den}, ${r.min}, ${r.increment}, ${q(r.status)}, ${q(r.verification)}, ${r.maxDelayDays}, ${arr(r.preconditions)}, ${q(r.sourceUrl)}, ${q(r.checkedAt)})`,
  ).join(',\n') + ';',
  '',
];
if (process.argv[2]) writeFileSync(process.argv[2], out.join('\n'), 'utf8');
else process.stdout.write(out.join('\n'));
